/** Static Deploy campus reference PDF bytes (Classroom-Layout-21-Sep-2026.pdf).
 * Served only behind Core deploy.read authorization in v1/services/deploy/service.mjs.
 */
export const LAYOUT_REFERENCE_FILENAME = "Classroom-Layout-21-Sep-2026.pdf";
const LAYOUT_REFERENCE_BASE64 =
  "";
let cachedBytes = null;
export function layoutReferenceBytes() {
  if (!cachedBytes) {
    const binary = atob(LAYOUT_REFERENCE_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    cachedBytes = bytes;
  }
  return cachedBytes;
}
export function layoutReferenceResponse() {
  return new Response(layoutReferenceBytes(), {
    headers: {
      "content-type": "application/pdf",
      "content-disposition": `attachment; filename="${LAYOUT_REFERENCE_FILENAME}"`,
      "cache-control": "private, no-store",
      "x-content-type-options": "nosniff",
    },
  });
}
